+<!DOCTYPE html>
+<html lang="en">
+<head>
+    <meta charset="UTF-8">
+    <meta name="viewport" content="width=device-width, initial-scale=1.0">
+    <title>Snake Game</title>
+    <style>
+        body {
+            display: flex;
+            justify-content: center;
+            align-items: center;
+            min-height: 100vh;
+            margin: 0;
+            padding: 20px;
+            background: #090d16;
+        }
+        .game-container {
+            background: rgba(16, 24, 40, 0.75);
+            backdrop-filter: blur(20px);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+        }
+        .game-header {
+            display: flex;
+            justify-content: space-between;
+            padding: 12px 20px;
+        }
+        .score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .high-score {
+            font-family: 'Inter', sans-serif;
+            font-size: 24px;
+            color: #fff;
+        }
+        .start-game-overlay {
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            background: rgba(16, 24, 40, 0.75);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+        }
+        .game-over-overlay {
+            position: absolute;
+            top: 50%;
+            left: 50%;
+            transform: translate(-50%, -50%);
+            background: rgba(16, 24, 40, 0.75);
+            padding: 20px;
+            border-radius: 10px;
+            box-shadow: 0 0 30px rgba(56, 189, 248, 0.4);
+            display: none;
+        }
+        .game-over-overlay.show {
+            display: flex;
+            flex-direction: column;
+            align-items: center;
+        }
+    </style>
+</head>
+<body>
+    <div class="game-container">
+        <div class="game-header">
+            <span class="score">Score: <span id="score">0</span></span>
+            <span class="high-score">High Score: <span id="high-score">0</span></span>
+        </div>
+        <canvas id="gameCanvas" width="400" height="400"></canvas>
+        <div class="start-game-overlay">
+            <h2>Start Game</h2>
+            <p>Use arrow keys or touch controls to play.</p>
+            <button id="play-button">Play</button>
+        </div>
+        <div class="game-over-overlay">
+            <h2>Game Over</h2>
+            <p>Final Score: <span id="final-score">0</span></p>
+            <button id="replay-button">Replay</button>
+        </div>
+    </div>
+    <script>
+        const canvas = document.getElementById('gameCanvas');
+        const ctx = canvas.getContext('2d');
+        const scoreElement = document.getElementById('score');
+        const highScoreElement = document.getElementById('high-score');
+        const finalScoreElement = document.getElementById('final-score');
+        const playButton = document.getElementById('play-button');
+        const replayButton = document.getElementById('replay-button');
+        const startGameOverlay = document.querySelector('.start-game-overlay');
+        const gameOverOverlay = document.querySelector('.game-over-overlay');
+        let score = 0;
+        let highScore = localStorage.getItem('highScore') || 0;
+        let snake = [
+            { x: 200, y: 200 },
+            { x: 190, y: 200 },
+            { x: 180, y: 200 }
+        ];
+        let direction = 'right';
+        let food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+        let lastTick = 0;
+        let gameOver = false;
+        function draw() {
+            ctx.clearRect(0, 0, canvas.width, canvas.height);
+            for (let i = 0; i < snake.length; i++) {
+                ctx.fillStyle = 'rgba(56, 189, 248, 0.4)';
+                ctx.fillRect(snake[i].x, snake[i].y, 10, 10);
+            }
+            ctx.fillStyle = 'rgba(255, 0, 0, 0.4)';
+            ctx.fillRect(food.x, food.y, 10, 10);
+        }
+        function update() {
+            const now = Date.now();
+            if (now - lastTick < 100) return;
+            lastTick = now;
+            for (let i = snake.length - 1; i > 0; i--) {
+                snake[i] = { ...snake[i - 1] };
+            }
+            if (direction === 'right') {
+                snake[0].x += 10;
+            } else if (direction === 'left') {
+                snake[0].x -= 10;
+            } else if (direction === 'up') {
+                snake[0].y -= 10;
+            } else if (direction === 'down') {
+                snake[0].y += 10;
+            }
+            if (snake[0].x === food.x && snake[0].y === food.y) {
+                score++;
+                scoreElement.textContent = score;
+                food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+                snake.push({ x: snake[snake.length - 1].x, y: snake[snake.length - 1].y });
+            }
+            if (snake[0].x < 0 || snake[0].x >= canvas.width || snake[0].y < 0 || snake[0].y >= canvas.height) {
+                gameOver = true;
+            }
+            for (let i = 1; i < snake.length; i++) {
+                if (snake[0].x === snake[i].x && snake[0].y === snake[i].y) {
+                    gameOver = true;
+                }
+            }
+            if (gameOver) {
+                finalScoreElement.textContent = score;
+                gameOverOverlay.classList.add('show');
+            }
+            draw();
+        }
+        function handleKey(event) {
+            if (event.key === 'ArrowUp' && direction !== 'down') {
+                direction = 'up';
+            } else if (event.key === 'ArrowDown' && direction !== 'up') {
+                direction = 'down';
+            } else if (event.key === 'ArrowLeft' && direction !== 'right') {
+                direction = 'left';
+            } else if (event.key === 'ArrowRight' && direction !== 'left') {
+                direction = 'right';
+            }
+        }
+        document.addEventListener('keydown', handleKey);
+        playButton.addEventListener('click', () => {
+            startGameOverlay.style.display = 'none';
+            update();
+            setInterval(update, 100);
+        });
+        replayButton.addEventListener('click', () => {
+            gameOver = false;
+            score = 0;
+            scoreElement.textContent = score;
+            snake = [
+                { x: 200, y: 200 },
+                { x: 190, y: 200 },
+                { x: 180, y: 200 }
+            ];
+            direction = 'right';
+            food = { x: Math.floor(Math.random() * 40) * 10, y: Math.floor(Math.random() * 40) * 10 };
+            gameOverOverlay.classList.remove('show');
+            update();
+            setInterval(update, 100);
+        });
+    </script>
+</body>
+</html>

